describe('Document Language Declaration', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should declare language in HTML tag for accessibility compliance', () => {
    cy.get('html').should('have.attr', 'lang');
    cy.get('html').invoke('attr', 'lang').should('not.be.empty');
    cy.get('html').invoke('attr', 'lang').should('match', /^[a-z]{2}(-[A-Z]{2})?$/);
  });

  it('should have valid language code format in HTML tag', () => {
    cy.get('html').then(($html) => {
      const lang = $html.attr('lang');
      expect(lang).to.exist;
      expect(lang).to.match(/^[a-z]{2}(-[A-Z]{2})?$/);
      expect(['en', 'es', 'fr', 'de', 'it', 'pt', 'ja', 'zh', 'en-US', 'en-GB', 'es-ES', 'pt-BR']).to.include(lang);
    });
  });

  it('should maintain language declaration across page navigation', () => {
    cy.get('html').invoke('attr', 'lang').as('initialLang');
    cy.get('a').first().click({ force: true }).catch(() => {});
    cy.get('html').invoke('attr', 'lang').then((currentLang) => {
      cy.get('@initialLang').then((initialLang) => {
        expect(currentLang).to.equal(initialLang);
      });
    });
  });

  it('should not have empty or whitespace-only language attribute', () => {
    cy.get('html').invoke('attr', 'lang').then((lang) => {
      expect(lang).to.exist;
      expect(lang.trim()).to.have.length.greaterThan(0);
      expect(lang).to.not.equal('');
      expect(lang).to.not.match(/^\s+$/);
    });
  });

  it('should have language attribute accessible to screen readers', () => {
    cy.get('html')
      .should('have.attr', 'lang')
      .and('not.be.empty');

    cy.get('html').then(($html) => {
      const computedStyle = window.getComputedStyle($html[0]);
      expect(computedStyle.display).to.not.equal('none');
    });
  });

  it('should handle regional language variants correctly', () => {
    cy.get('html').invoke('attr', 'lang').then((lang) => {
      if (lang.includes('-')) {
        const parts = lang.split('-');
        expect(parts).to.have.lengthOf(2);
        expect(parts[0]).to.match(/^[a-z]{2}$/);
        expect(parts[1]).to.match(/^[A-Z]{2}$/);
      } else {
        expect(lang).to.match(/^[a-z]{2}$/);
      }
    });
  });

  it('should validate language attribute is set before DOM content loads', () => {
    cy.document().then((doc) => {
      const htmlElement = doc.documentElement;
      expect(htmlElement.hasAttribute('lang')).to.be.true;
      expect(htmlElement.getAttribute('lang')).to.not.be.null;
    });
  });

  it('should ensure language attribute is not dynamically removed', () => {
    cy.get('html').invoke('attr', 'lang').as('langBefore');
    cy.wait(1000);
    cy.get('html').invoke('attr', 'lang').then((langAfter) => {
      cy.get('@langBefore').then((langBefore) => {
        expect(langAfter).to.equal(langBefore);
      });
    });
  });
});
